import{z as l,x as i,o as s,c as P,q as A,j as o,D as e,d as a,s as r,S as n,b as B}from"./chunks/framework.C8m1ZpeB.js";const m=JSON.parse('{"title":"任播与边缘","description":"","frontmatter":{"title":"任播与边缘","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/anycast-edge.md","filePath":"cs/anycast-edge.md","lastUpdated":1791063341000}'),d={name:"cs/anycast-edge.md"};function p(D,E,C,c,h,F){const t=i("Mermaid");return s(),P("div",null,[E[2]||(E[2]=A('<h1 id="任播与边缘" tabindex="-1">任播与边缘 <a class="header-anchor" href="#任播与边缘" aria-label="Permalink to &quot;任播与边缘&quot;">​</a></h1><div class="epigraph"><p>同一前缀从多处宣告，分组被路由到「最近」的实例；CDN 用它把用户送到边上的缓存节点。</p><footer>—— 据 Kurose and Ross；对照 RFC 4786 对任播操作的讨论；Nygren 等对 CDN</footer></div><p><a href="/cs/cdn-intuition">上一课</a>给出边缓存与请求导向。本课不重讲为何复制对象。缺口是导向手段之一：<strong>任播</strong>——多点宣告同一地址，靠 <a href="/cs/bgp-policy">BGP</a> 与 <a href="/cs/lpm">LPM</a> 把用户送进最近的 PoP。DNS 导向是另一手段，上一课已点名。本课不把套接字 API 提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>CDN 直觉留下「DNS 或任播」。DNS 按解析器位置返回不同 A/AAAA，粒度是解析器不是客户。任播：边缘节点共享前缀，路由自然选近。TCP 连接必须粘在同一实例上：路径变化会把后续段送到另一台没有状态的机器。缺口是<strong>用路由当负载均衡</strong>及其与有状态传输的张力。</p><p><span class="marginnote">术语翻译：任播（anycast）就是同一个 IP 地址由多台机器同时对外宣告，路由协议自动把每个用户送到「网络距离最近」的那一台。对照记忆：单播是一个地址一台主机，广播是一个地址全体接收，任播是一个地址一群实例、谁近谁接。</span></p><p><span class="marginnote">无状态的 UDP DNS 很适合任播。HTTPS 依赖稳定路径或把状态同步到任播集合——工程上常「任播到 PoP，PoP 内再用本地负载均衡」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>运营商在多地宣告同一覆盖前缀。用户的 SYN 到达某边缘，该边缘完成 <a href="/cs/tcp-handshake">TCP 握手</a> 与 <a href="/cs/http-tls-entry">TLS 入口</a>。缓存命中则本地答；未命中回源。故障时撤宣告，前缀收敛到活着的点。与单播对照：地址不再标识唯一主机，标识的是服务。</p><p><span class="marginnote">常见误区：「最近」不等于地理最近。BGP 选路按路由策略、跳数与商业关系度量——北京的用户完全可能被送进「路由度量更近」的东京节点而不是上海。把它理解成连锁店共用一个客服热线：系统只管把来电转给「话务上最近」的门店，不管地图距离。</span></p>',10)),(s(),o(n,null,{default:e(()=>[r(t,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E5%88%86%E7%BB%84%22%5D%20--%3E%20BGP%5B%22%E6%8C%89%E4%BB%BB%E6%92%AD%E5%89%8D%E7%BC%80%20LPM%22%5D%0A%20%20BGP%20--%3E%20EDGE%5B%22%E6%9C%80%E8%BF%91%E8%BE%B9%E7%BC%98%E5%AE%9E%E4%BE%8B%22%5D%0A%20%20EDGE%20--%3E%20HIT%5B%22%E7%BC%93%E5%AD%98%E5%91%BD%E4%B8%AD%22%5D%0A%20%20EDGE%20--%3E%20ORIGIN%5B%22%E5%9B%9E%E6%BA%90%22%5D%0A"})]),fallback:e(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("任播把控制平面政策变成「距离」上的选路，边缘把 "),B("a",{href:"/cs/http-semantics"},"HTTP 缓存头"),a(" 的允许落到地理上。它不提供新的端到端可靠性；路径漂移是任播的经典故障。安全：证书仍绑名字，不绑任播地址本身。")],-1)),E[5]||(E[5]=B("p",null,"任播的经典故障长什么样？一条已建立的 TCP 连接遇上 BGP 重新收敛：",-1)),(s(),o(n,null,{default:e(()=>[r(t,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20EST%5B%22TCP%20%E8%BF%9E%E6%8E%A5%E5%B7%B2%E5%BB%BA%E7%AB%8B%EF%BC%9A%E4%BC%9A%E8%AF%9D%E7%8A%B6%E6%80%81%E5%8F%AA%E5%9C%A8%20PoP%20A%22%5D%20--%3E%20CH%5B%22BGP%20%E6%94%B6%E6%95%9B%EF%BC%9A%E6%9B%B4%E8%BF%91%E8%B7%AF%E5%BE%84%E6%94%B9%E6%8C%87%20PoP%20B%22%5D%0A%20%20CH%20--%3E%20PKT%5B%22%E5%90%8E%E7%BB%AD%E5%88%86%E7%BB%84%E4%BB%8D%E5%8F%91%E5%BE%80%E5%90%8C%E4%B8%80%E4%B8%AA%E4%BB%BB%E6%92%AD%E5%9C%B0%E5%9D%80%22%5D%0A%20%20PKT%20--%3E%20Q%7B%22%E8%BF%99%E6%89%B9%E5%88%86%E7%BB%84%E8%90%BD%E5%88%B0%E8%B0%81%E6%89%8B%E9%87%8C%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E4%BB%8D%E6%94%B6%E6%95%9B%E5%88%B0%20PoP%20A%22%7C%20CONT%5B%22%E7%8A%B6%E6%80%81%E5%AF%B9%E5%BE%97%E4%B8%8A%EF%BC%8C%E8%BF%9E%E6%8E%A5%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20Q%20--%3E%7C%22%E8%90%BD%E5%88%B0%20PoP%20B%EF%BC%9A%E6%B2%A1%E6%9C%89%E8%BF%99%E6%9D%A1%E8%BF%9E%E6%8E%A5%22%7C%20RST%5B%22%E6%97%A0%E7%8A%B6%E6%80%81%E5%8F%AF%E6%9F%A5%EF%BC%9A%E5%9B%9E%20RST%20%E6%88%96%E4%B8%A2%E5%8C%85%EF%BC%8C%E4%BC%9A%E8%AF%9D%E4%B8%AD%E6%96%AD%22%5D%0A%20%20FIX%5B%22%E5%B7%A5%E7%A8%8B%E5%AF%B9%E7%AD%96%EF%BC%9A%E4%BB%BB%E6%92%AD%E5%8F%AA%E9%80%81%E5%88%B0%20PoP%20%E5%85%A5%E5%8F%A3%EF%BC%8CPoP%20%E5%86%85%E5%86%8D%E7%B2%98%E4%BD%8F%E5%9B%BA%E5%AE%9A%E5%90%8E%E7%AB%AF%22%5D%0A%20%20RST%20--%3E%20FIX%0A"})]),fallback:e(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=A('<p><span class="marginnote">为什么重要：任播的「容错」只对无状态流量免费——UDP DNS 丢一包重问即可；对 TCP 则不然，路由一收敛，在途连接可能被送进一台从没见过这个四元组的机器。所以 CDN 的标准做法是任播只负责「进门」，进门之后会话固定在同一台机器上，不让用户在 PoP 之间漂。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把全球 Anycast 的测量论文当必读，不引入把 TCP 状态在 PoP 间实时迁移的全部方案。应用如何拿到描述符并读写，下一课套接字 API。</p><p>后课默认：同一地址可以表示一群边缘。进程眼里的端点是套接字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>任播靠路由把用户送到近处实例。</li><li>有状态传输要粘会话或把状态留在 PoP 内。</li><li>套接字 API 下一课。</li><li>出处：Kurose and Ross；RFC 4786；对照 CDN 文献。</li></ul>',6))])}const f=l(d,[["render",p]]);export{m as __pageData,f as default};
